// Section order and layouts follow the five supplied InDesign template PDFs.
// These helpers emit ordinary, editable Shrubbery Markdown.
const block=(kind,text)=>`{{${kind}\n${text}\n}}`;
const cols=(...parts)=>block(`columns,${parts.length===3?'three':'two'}`,parts.join('\n\n\\column\n\n'));
const split=(kind,...parts)=>block(`columns,${kind}`,parts.join('\n\n\\column\n\n'));
const bullets=(n,prompt)=>Array.from({length:n},(_,i)=>`- ${prompt} ${i+1}: add a specific detail.`).join('\n');
const fields=(names,prompt='Describe this detail.')=>block('fields',names.map(n=>`**${n}:** ${prompt}`).join('\n'));
const quote=()=>block('flavor','Write an evocative account of this place in a local voice.\n\nAdd a second passage that hints at its character or history.\n\n— Speaker or source');
const page=(text,background='canopy',size='wildsea')=>`{{page background=${background} size=${size}}}\n${block('compact',text)}`;
const join=pages=>pages.join('\n\n\\page\n\n')+'\n';
const feature=i=>`### Feature ${i} {{accent (Feature Type)}}\nDescribe the feature and how visitors interact with it.\n\n*Add a specific or unusual detail.*`;
const place=(type)=>`## ${type} Name {{accent (${type==='Port'?'Type':type})}}\n${fields(['Factoid name','Factoid name'],'Add a quantity or short description.')}\nIntroduce the location and what distinguishes it.\n\n${[1,2,3].map(feature).join('\n\n')}`;
const principles=`### Principles\nDescribe what holds the faction together.\n${bullets(3,'Principle')}\n\n### Quick NPCs\n${bullets(3,'**NPC name (Bloodline)**')}`;
const hooks=`### Story Hooks\n${bullets(6,'Hook')}`;
const faction=`## Faction Name {{accent (Faction)}}\n${fields(['Home Turf','Motivation'])}\nIntroduce the faction and its place in the reach.\n\n${[1,2,3].map(feature).join('\n\n')}`;
const aspects=(count,start=1)=>Array.from({length:count},(_,i)=>`#### Aspect ${start+i} {{accent (Track Length + Type)}}\nDescribe the ability, its limits, and when it applies.`).join('\n\n');
const smallHazard=`## Hazard Name\n**{{accent [Size] Brief Descriptor Phrase}}**\n\nDescribe the hazard. *Explain when and why to use it.*\n\n### Presence\n${fields(['Sight','Smell'])}\n### Resources\n${fields(['Salvage','Charts'],'List a few examples, separated by commas.')}\n### Aspects\n${fields(['Aspect name'])}\n### Quirks\n${fields(['Quirk one','Quirk two','Quirk three','Quirk four'])}`;
const hazardCore=`# Hazard Name\n**{{accent [Size] Brief Descriptor Phrase}}**\n\nDescribe its nature, behaviour, and place in the world.\n\n*Explain when and why to use this hazard.*\n\n## Drives\n${fields(['Drive name'],'Describe what it wants and how it pursues it.')}\n## Presence\n${fields(['Sight','Sound','Smell','Taste'])}\n## Resources\n${fields(['Specimens','Whispers'],'List a few examples, separated by commas.')}`;
const hazardAspects=`## Aspects\n${fields(['Aspect one','Aspect two','Aspect three'],'Describe a distinctive ability or limitation.')}`;
const characterIntro=`# CHARACTER ELEMENT {{accent TYPE}}\n*The building blocks of a Wildsea character.*\n\nIntroduce this bloodline, origin, or post and its role in the world.\n\nDescribe how its people live and how they relate to a crew.\n\n### Subsection One\nDevelop a defining physical, cultural, or practical detail.\n\n### Subsection Two\nExplore a second theme and the choices it offers players.\n\n### Questions to Consider\nWhen incorporating this element into a character, consider:\n${bullets(3,'Character question')}\n\n### Alternate Presentations\nSuggest other ways to interpret the element without losing its identity.`;
const kit=`## QUICKSTART KIT\nWhen making a quickstart character, choose from these options.\n\n### Edge {{accent (Choose 1)}}\nOption one, option two, option three.\n\n### Skills & Languages {{accent (Choose 5)}}\n${fields(['Skills','Languages'],'List ten choices in total across these two rows.')}\n### Resources {{accent (Choose 2)}}\n${fields(['Salvage','Specimens','Whispers','Charts'],'List six choices in total across these four rows.')}\n### Drive {{accent (Choose 1)}}\n${bullets(2,'Drive')}\n### Mire {{accent (Choose 1)}}\n${bullets(2,'Mire')}`;
export const ASPECTS=page(split('two-one',`# ASPECTS\nDescribe how these aspects make the character unique. During quickstart creation, choose two.\n\n${cols(aspects(9),aspects(7,10))}`,kit));
const reachPages=[
 page(block('cover','# REACH\n# NAME\n\nReplace this title with the name of your reach.'),'reach'),
 page(split('one-two',quote(),`# Main Elements\nThis page highlights the most important elements of **Reach Name**, a reach of **detail one, detail two, and detail three**. The following pages explore them in detail.\n\n${['One','Two','Three','Four','Five'].map(n=>`### Subsection ${n}\nDescribe one defining element of the reach. Crews might encounter…\n${bullets(3,'Descriptor')}`).join('\n\n')}`),'reach'),
 page(cols('',place('Territory'),place('Territory')),'reach'),
 page(cols(place('Territory'),block('box',`## Local Rumours\n${bullets(8,'Rumour')}`),''),'reach'),
 page(cols(quote(),place('Port'),place('Port'))),
 page(cols(place('Port'),'','')),
 page(cols(quote(),faction,principles+'\n\n'+hooks)),
 page(cols(faction,principles,hooks)),
 page(`# FIREFLY RESOURCES\n${split('one-two',block('box',['Peace','Order','Nature'].map(n=>`### Watch Results {{accent (${n})}}\n${fields(['6','5','4','3','2','1'],'Describe a watch result.')}`).join('\n')),block('box',`## Trade Goods & Cargo\n${bullets(6,'**Goods / Cargo Name (import or export)**')}`)+'\n'+cols(block('box',`## Passengers\n${bullets(6,'Passenger')}`),block('box',`## Endemic Hazards\n${bullets(6,'Hazard')}`)))}`),
 page(cols(smallHazard,`## Element Name {{accent TYPE}}\n*Write a quick tagline.*\n\nIntroduce a character element connected to the reach.\n\n${[1,2,3].map(i=>`### Detail ${i}\nExplain a defining characteristic and what it means in play.`).join('\n\n')}`,`## Aspects\n${aspects(8)}`))
];
const moments=()=>`### POTENTIAL MOMENTS\n${fields(Array.from({length:6},(_,i)=>`Moment ${i+1}`),'Describe an opportunity, clue, or turn of events.')}`;
const act=(n)=>`## THE ${n} ACT {{accent (Focus of Act)}}\n### OVERVIEW\nDescribe what happens in this act.\n\n*The act ends when: specify a transition.*\n\n### THE FIREFLY SHOULD…\n${bullets(n==='SECOND'?4:3,'Action')}\n\n### THE CREW COULD…\n${bullets(n==='THIRD'?4:2,'Possibility')}`;
const quickPages=[page(block('banner','# SCENARIO NAME\n**SESSION OVERVIEW** — Summarize what to expect in two or three sentences.')+'\n'+split('two-one',cols(act('FIRST'),moments())+'\n'+block('banner',`## PRE-GAME CHECKS\nIntroduce the world, check safety tools, read the starter text, and ask unsetting questions.\n\n### STARTER TEXT {{accent (READ ALOUD)}}\nWrite the opening description of the scene.\n\nAdd a second paragraph establishing the crew’s immediate situation.\n\n### UNSETTING QUESTIONS {{accent (ASK EVERY PLAYER)}}\n${bullets(3,'Unsetting question')}`),`### DESCRIBING THE SCENE\nDescribe the atmosphere and sensory details.\n\n**Points of Interest:** Place / Place / Place / Detail / Detail / Detail\n\n### NPC NAME {{accent (BLOODLINE)}}\nDescribe their manner, role, and connection to this scene.`),'canopy','letter'),
 page(cols(act('SECOND')+'\n'+moments()+'\n### CLIMAX OF THE SESSION\nDescribe the central confrontation and what is at stake.',act('THIRD')+'\n'+moments()+'\n'+block('box','### SPICING THINGS UP\nSuggest a complication for experienced Fireflies.'),block('box',`## Hazard Name\n**{{accent [Size] Brief Descriptor Phrase}}**\n\nDescribe the principal threat.\n\n### Drives\n${fields(['Drive one','Drive two'])}\n### Encounter Tracks\n${[1,2,3].map(i=>`**Track ${i}:** {{track 3|2}}\n\nMark when a trigger occurs. At completion, describe what changes.`).join('\n\n')}\n### Presence\n${fields(['Sight','Sound','Smell'])}\n### Resources\n${fields(['Specimens','Whispers'])}\n### Aspects\n${fields(['Aspect one','Aspect two','Aspect three'])}`)),'canopy','letter')];
const sceneFields=(name)=>`### ${name}\n${fields(['Essentials','Suggested Resources','Points of Interest'])}\nDescribe the place and its atmosphere.\n\n*Add a specific detail or clue for the Firefly.*`;
const threads=()=>block('box',`## Snapshots & Story Threads\nPrepare responses to likely choices without prescribing a path.\n\n${fields(['If the crew…','If the crew…','If the crew…','If the crew…'],'Describe the consequence or discovery.')}`);
const senses=`## Describing Location\n${bullets(4,'Sensory detail')}`;
const campaignHook=()=>block('box',`## Scenario / Hook Name\nDescribe the next adventure, its connection to this scenario, and the stakes.\n\nThe crew might discover…\n${bullets(3,'Discovery')}`);
const scenarioPages=[
 page(block('cover','### AUTHOR NAME\n# THE WILDSEA\n## SCENARIO — SCENARIO NAME'),'reach'),
 page(split('one-two',quote(),`# Overview\nSummarize the premise, tone, and likely scope of play.\n\n## Pre-Game Suggestions\nSuggest useful character choices and preparations.\n${bullets(3,'**Suggestion**')}\n\n## Sample Unsetting Questions\nUse these to connect the crew to the adventure.\n${bullets(3,'Unsetting question')}`),'reach'),
 page(split('two-one',`# Core Truths\nDescribe the underlying situation and what is actually happening.\n\n### Starting Hook / Premise\n${fields(['Info to Collect','The Big Reveal'])}\n${[1,2,3].map(i=>`### Detail About Adventure ${i}\nExplain an important truth.\n${fields(['Investigation Reveals','The Big Reveal'])}`).join('\n')}`,`## Adventure Framework\nDescribe connections between locations, leaving the route to the crew.\n\n${[1,2,3,4,5].map(i=>`### Location ${i}\nDescribe its role and connections to other locations.`).join('\n\n')}`),'reach'),
 page(split('two-one',`# Simple Location\nIntroduce the location and its immediate situation.\n\n### When the Crew Arrive, You Might…\n${bullets(4,'Action')}\n${cols(senses,`## Notable Places\n${sceneFields('Place Name (Type)')}`)}`,sceneFields('Place Name (Type)')+'\n'+sceneFields('Place Name (Type)')),'reach'),
 page(cols(threads(),...Array.from({length:2},()=>`## Notable Locals\n${[1,2].map(()=>`### Local Name {{accent (Role in Community)}}\n${fields(['Essentials','Specialties','Attitude','Appearance'])}\nDescribe a hook, clue, or red herring this local offers.`).join('\n\n')}`)),'reach'),
 page(split('two-one',`# Complex Location\nDescribe its identity and uncertain history.\n\n### LOCATION Is Definitely…\n${bullets(3,'Fact')}\n### LOCATION Might Be…\n${bullets(3,'Possibility')}\n### When the Crew Arrive, You Might…\n${bullets(4,'Action')}`,block('box',`## Entering the Location\nDescribe the obstacles to entry.\n${bullets(4,'Suggested approach')}`))+'\n'+block('banner','## Generating Rooms\nCombine a room, a feature, and a detail to build each space.')+'\n'+cols(...['Room','Feature','Detail'].map(n=>block('box',`### ${n}\n${fields(['1','2','3','4','5','6','A','B'],`Add a ${n.toLowerCase()} fragment.`)}`))),'reach'),
 page(cols(senses,threads(),''),'reach'),
 page(cols(quote(),`# Skinning the Location\nExplain alternative presentations of the location.\n\n${sceneFields('Feature / Room (Standard)')}`,sceneFields('Feature / Room (Standard)')+'\n'+sceneFields('Feature / Room (Standard)')),'reach'),
 page(split('two-one',cols(sceneFields('Feature / Room (Specific Use Case)')+'\n'+sceneFields('Feature / Room (Specific Use Case)'),sceneFields('Feature / Room (Specific Use Case)')),block('box',`## The Crescendo!\nDescribe the final scene and the stakes.\n${bullets(3,'Possible form of the finale')}`))+'\n'+block('box',`## When the Dust Settles…\nDescribe the aftermath and rewards. Offer these aspects if appropriate.\n\n${cols(aspects(2),aspects(2,3))}`),'reach'),
 page(split('one-two',quote(),`# Leading Into a Campaign\nDescribe how the outcome opens further adventures.\n${bullets(5,'If the crew did something…')}\n\n${campaignHook()}`),'reach'),
 page(cols(campaignHook()+'\n'+campaignHook(),campaignHook()+'\n'+campaignHook()),'reach'),
 page(cols(`# Hazards & Encounters\nDescribe how to introduce threats and keep encounters varied.\n\n## When Setting Up a Hazard, You Should…\n${fields(['Drives','Presence','Quirks','Tracks'],'Explain how to use this during the encounter.')}\n## When Managing Focus In An Encounter, You Should…\n${fields(['Focus track','Open or hidden','Sharing the spotlight','Time to rest'],'Add guidance for the Firefly.')}`,hazardCore+'\n'+hazardAspects),'reach'),
 page(split('one-two',`## Quirks\n${fields(['Quirk one','Quirk two','Quirk three','Quirk four'])}`,block('box',[1,2].map(i=>`### DIFFICULTY Encounter — Encounter ${i}\n{{track 3|2|5}}\n\nDescribe the situation, what marks the track, and how the encounter changes at each break.`).join('\n\n'))),'reach'),
 page('# Credits and Legal\nCredit the writers, editors, playtesters, artists, and font sources.\n\n'+fields(['Writing','Editing','Art','Layout','Playtesting','Fonts'],'Replace with the appropriate names and required attribution.')+'\n\nAdd any additional credits or permissions required for your material. The document’s license notice is printed in the footer.')
];
export const TEMPLATES={
 reach:{label:'Reach',detail:'10 pages · main elements, territories, ports, factions, resources',text:join(reachPages)},
 character:{label:'Character element',detail:'2 pages · introduction, 16 aspects, quickstart kit',text:join([page(cols('',characterIntro),'reach'),ASPECTS])},
 aspects:{label:'Character aspects',detail:'1 page · 16 aspects and a quickstart kit',text:ASPECTS+'\n'},
 hazard:{label:'Hazard',detail:'2 pages · full hazard, hooks, compact variants',text:join([page(cols(hazardCore,hazardAspects+'\n## Quirks\n'+fields(['Quirk one','Quirk two','Quirk three','Quirk four','Quirk five']),`## Hooks & Encounters\n${fields(['Hook / Encounter one','Hook / Encounter two','Hook / Encounter three','Hook / Encounter four'],'Describe the situation. *Suggest how to introduce it.*')}`),'reach'),page(cols(smallHazard,'### Hazard Name\nDescribe a brief hazard and when to use it.\n\n### Hazard Name\nDescribe another brief hazard and when to use it.','### Hazard Name\nDescribe a third brief hazard and when to use it.'))])},
 quickplay:{label:'Quickplay',detail:'2 Letter pages · three acts, pre-game checks, hazard reference',text:join(quickPages)},
 scenario:{label:'Scenario',detail:'14 pages · locations, locals, rooms, finale, hooks, encounters',text:join(scenarioPages)}
};
